def max_distinct_window_sum(nums, w):
    n = len(nums)
    if w <= 0 or w > n:
        return -1

    counts = {}
    window_sum = 0
    for i in range(w):
        counts[nums[i]] = counts.get(nums[i], 0) + 1
        window_sum += nums[i]

    best = window_sum if len(counts) == w else -1

    for i in range(w, n):
        out, inc = nums[i - w], nums[i]
        counts[out] -= 1
        if counts[out] == 0:
            del counts[out]
        counts[inc] = counts.get(inc, 0) + 1
        window_sum += inc - out
        if len(counts) == w and window_sum > best:
            best = window_sum

    return best
```

A window has all distinct values exactly when its count map holds w keys, so I slide one element at a time, updating the sum and the map, and track the best valid sum. Time is O(n) and space is O(w).
